                      std::cerr << "HARNESS NETWORK simulated announcement, no printer involved\n";
                      wxGetApp().getDeviceManager()->on_machine_alive(
                          nlohmann::json{{"dev_name", "P1s"}, {"dev_id", "01P00C652900116"}, {"dev_ip", address}, {"dev_type", "C12"},
