void AgentHost::begin_tool_followup(const PendingToolContinuation& continuation)
{
    ProjectStateDocument& document = m_persistence.document();
    ConversationMessage assistant;
    assistant.id          = document.allocate_message_id();
    assistant.role        = MessageRole::Assistant;
    assistant.state       = MessageState::Streaming;
    assistant.in_reply_to = continuation.user_message_id;
    assistant.created_at = m_persistence.timestamp();
    document.append_message(continuation.conversation_id, assistant, assistant.created_at);
    m_persistence.commit();

    ActiveStream stream;
    stream.conversation_id = continuation.conversation_id;
    stream.message         = assistant;
    m_stream               = std::move(stream);
    send_envelope(Protocol::kAssistantStarted,
                  json{{"messageId", assistant.id}, {"inReplyTo", assistant.in_reply_to}, {"attempt", assistant.attempt}}.dump());
}

// The top handler of the AI request's pump, which each panel's timer runs.
    json                        lost  = json::array();
    for (const std::string& id : bound_before)
        if (!bound.count(id))
            lost.push_back(id);
    return lost;
}

bool ToolExecutionCoordinator::refuse_slice_poll(ToolActivity& activity)
{
    if (activity.source != ToolSource::Agent || !m_slice_running)
        return false;
    const ToolActivity* started = find(m_slice_handle);
    if (started == nullptr || started->source != ToolSource::Agent)
        return false;
    const bool same_turn = m_same_turn ? m_same_turn(started->correlation_id, activity.correlation_id)
                                       : started->correlation_id == activity.correlation_id;
    if (!same_turn)
        return false;
    ++m_refused_slice_polls;
    fail(activity, "busy", "The slice is still running. This turn has nothing left to do: the app starts a new turn with the outcome. Finish your reply.");
    return true;
}

